from .models import Box, Channel, Link


class SQLProbeTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.a1 = Channel.objects.create(network="a", slot="1", name="a1")
        cls.a2 = Channel.objects.create(network="a", slot="2", name="a2")
        cls.b1 = Channel.objects.create(network="b", slot="1", name="b1")
        ct = ContentType.objects.get_for_model(Channel)
        Link.objects.create(
            content_type=ct, object_id=json.dumps(["a", "1"]), kind="x", weight=10
        )
        Link.objects.create(
            content_type=ct, object_id=json.dumps(["a", "1"]), kind="y", weight=5
        )
        Link.objects.create(
            content_type=ct, object_id=json.dumps(["b", "1"]), kind="x", weight=99
        )

    def test_sqls(self):
        cases = {
            "basic": Channel.objects.filter(links__kind="x"),
            "distinct_in": Channel.objects.filter(
                links__in=Link.objects.filter(kind__in=["x", "y"])
            ),
            "conj": Channel.objects.filter(links__kind="x", links__weight=5),
            "exclude_split": Channel.objects.exclude(
                links__kind="y", links__weight=10
            ),
            "exclude_real": Channel.objects.exclude(
                links__kind="x", links__weight=10
            ),
            "or_not": Channel.objects.filter(
                Q(links__kind="z") | ~Q(links__kind="x")
            ),
            "neg_complex": Channel.objects.exclude(
                Q(links__kind="x") & Q(links__weight__gt=50)
            ),
            "range": Channel.objects.filter(
                links__weight__gte=5, links__weight__lte=20
            ),
            "nested_not": Channel.objects.exclude(
                Q(links__kind="z") | Q(links__weight=5)
            ),
        }
        for label, qs in cases.items():
            print(f"\n=== {label} ===")
            print(str(qs.query))
            print("RESULT:", sorted(qs.values_list("name", flat=True)))

